function redactPii(record) {
  if (record === null || record === undefined) {
    return record ?? null;
  }
  const copy = { ...record };
  for (const key of ["email", "phone", "card"]) {
    if (Object.prototype.hasOwnProperty.call(copy, key)) {
      copy[key] = "[redacted]";
    }
  }
  return copy;
}
